        context.getSharedPreferences("tango",0).edit().remove("chatgpt_reasoning_mode").commit();require((int)call(api,"selectedMode",new Class[]{})==1,"Model slider does not default to Medium");main(()->call(activity,"updateModelMode",new Class[]{}));
