        down=SystemClock.uptimeMillis();pointer(down,down,MotionEvent.ACTION_DOWN,point[0],point[2]);for(int step=1;step<=12;step++){SystemClock.sleep(16);pointer(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_MOVE,point[0]+(point[1]-point[0])*step/12f,point[2]);if(step==6){test.waitForIdleSync();require((int)call(api,"selectedMode",new Class[]{})==1,"Dragging through the capsule center does not select Medium");}}
        pointer(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,point[1],point[2]);test.waitForIdleSync();SystemClock.sleep(180);require((int)call(api,"selectedMode",new Class[]{})==2,"Dragging to the capsule end does not select High");require(!(boolean)field(activity,"drawerVisible"),"Swiping the effort control incorrectly opens the drawer");main(()->call(activity,"dismissComposerOverlay",new Class[]{boolean.class},false));checks.put("uiCustomEffortPickerRespondsToTapAndDrag",true);
